   1:  UFRAME_NUM=1 ;
   2:  UTOOL_NUM=1 ;
   3:  !Pick from conveyor and place on fixture A ;
   4:  !Approach points used for smooth transitions ;
   5:  !Contact moves at 50mm/sec, travel at 100mm/sec ;
   6:  !Gripper close then wait to settle 1.0s (user requested 'gently') ;
   7:  !Use FINE termination for precise stops ;
   8:  J PR[1:home] 100% FINE ;
   9:  L PR[6:conveyor approach] 100mm/sec CNT50 ;
